        foreach ($posts as $data) {
            $cat = $data['category'];
            $imagePath = "blog-posts/{$data['slug']}.jpg";
            $this->download(
                "https://picsum.photos/seed/{$data['slug']}/" . self::THUMB_W . '/' . self::THUMB_H,
                $imagePath
            );

            $post = BlogPost::firstOrCreate(
                ['slug' => $data['slug']],
                [
                    'author_id'        => $authorId,
                    'blog_category_id' => $cat,
                    'title'            => $data['title'],
                    'excerpt'          => $data['excerpt'],
                    'body'             => $data['body'],
                    'featured_image'   => Storage::disk('public')->exists($imagePath) ? $imagePath : null,
                    'status'           => 'published',
                    'published_at'     => Carbon::now()->subDays(rand(1, 120)),
                ]
            );

            if (Storage::disk('public')->exists($imagePath)) {
                $post->update(['featured_image' => $imagePath]);
            }

            $categoryIds = $data['extra_categories'];
            $categoryIds[] = $cat;
            $post->categories()->sync(array_unique($categoryIds));

            $tagIds = $data['tags'];
            $post->tags()->sync($tagIds);
        }
    }

    private function download(string $url, string $storagePath): void
    {
        if (Storage::disk('public')->exists($storagePath)) {
            return;
        }

        try {
            $response = Http::timeout(20)->get($url);
            if ($response->successful()) {
                Storage::disk('public')->put($storagePath, $response->body());
            }
        } catch (\Throwable) {
        }
    }
